for county,data in WI_COUNTIES.items():
    sections=[
        ('Wisconsin POWTS framework','Wisconsin Department of Safety and Professional Services identifies counties as having the primary responsibility to inspect Private Onsite Wastewater Treatment Systems, except for state-owned projects. DSPS also provides the statewide sanitary permit application, soil/site evaluation forms, inspection forms, and POWTS plan-review resources used with local county administration.'),
        ('Use current county and state approvals together','County sanitary permits are part of Wisconsin\'s POWTS regulatory system. Depending on system type and project scope, state plan approval or other review may be required in addition to the county permit. The county page below identifies the local filing path and should be checked before construction or alteration.'),
    ] + data['sections']
    sources=[('Wisconsin DSPS — Private Onsite Wastewater Treatment Systems',WI_POWTS)] + data['sources']
    write_county_page('Wisconsin','wisconsin',county,data['authority'],data['contact'],sections,sources,verified='August 29, 2026')

print(f'Wisconsin expansion complete: +{len(WI_COUNTIES)} verified county guides')
